INSERT INTO plan_pricing_tier (plan_id, tier_order, from_vehicle_count, to_vehicle_count, price_per_vehicle, created_at, updated_at)
SELECT id, 1, 31, 100, 2.50, CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6) FROM plan WHERE code = 'PLATINUM';

INSERT INTO plan_pricing_tier (plan_id, tier_order, from_vehicle_count, to_vehicle_count, price_per_vehicle, created_at, updated_at)
SELECT id, 1, 101, 200, 2.00, CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6) FROM plan WHERE code = 'FROTTA';

INSERT INTO plan_pricing_tier (plan_id, tier_order, from_vehicle_count, to_vehicle_count, price_per_vehicle, created_at, updated_at)
SELECT id, 2, 201, 500, 1.50, CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6) FROM plan WHERE code = 'FROTTA';

INSERT INTO plan_pricing_tier (plan_id, tier_order, from_vehicle_count, to_vehicle_count, price_per_vehicle, created_at, updated_at)
